import { toast } from "react-hot-toast";
import { apiConnector } from "../apiconnector";
import { courseEndpoints } from "../api";

const {
  COURSE_DETAILS_API,
  COURSE_CATEGORIES_API,
  GET_ALL_COURSE_API,
  CREATE_COURSE_API,
  EDIT_COURSE_API,
  CREATE_SECTION_API,
  CREATE_SUBSECTION_API,
  UPDATE_SECTION_API,
  UPDATE_SUBSECTION_API,
  DELETE_SECTION_API,
  DELETE_SUBSECTION_API,
  GET_ALL_INSTRUCTOR_COURSES_API,
  DELETE_COURSE_API,
  GET_FULL_COURSE_DETAILS_AUTHENTICATED,
  CREATE_RATING_API,
  LECTURE_COMPLETION_API,
} = courseEndpoints;

// Fetch all courses
export const getAllCourses = async () => {
  const toastId = toast.loading("Loading courses...");
  let result = [];
  try {
    const response = await apiConnector("GET", GET_ALL_COURSE_API);
    if (!response?.data?.success) {
      throw new Error("Failed to fetch courses.");
    }
    result = response.data.data;
    toast.success("Courses fetched successfully!");
  } catch (error) {
    console.error("GET_ALL_COURSE_API ERROR:", error);
    toast.error(error.message || "Failed to fetch courses.");
  } finally {
    toast.dismiss(toastId);
  }
  return result;
};

// Fetch course details by ID
export const fetchCourseDetails = async (courseId) => {
  const toastId = toast.loading("Loading course details...");
  let result = null;
  try {
    const response = await apiConnector("POST", COURSE_DETAILS_API, { courseId });
    if (!response.data.success) {
      throw new Error(response.data.message || "Failed to fetch course details.");
    }
    result = response.data;
    toast.success("Course details fetched successfully!");
  } catch (error) {
    console.error("COURSE_DETAILS_API ERROR:", error);
    toast.error(error.message || "Failed to fetch course details.");
  } finally {
    toast.dismiss(toastId);
  }
  return result;
};

// Fetch course categories
export const fetchCourseCategories = async () => {
  const toastId = toast.loading("Loading categories...");
  let result = [];
  try {
    const response = await apiConnector("GET", COURSE_CATEGORIES_API);
    if (!response?.data?.success) {
      throw new Error("Failed to fetch course categories.");
    }
    result = response.data.data;
    toast.success("Categories fetched successfully!");
  } catch (error) {
    console.error("COURSE_CATEGORIES_API ERROR:", error);
    toast.error(error.message || "Failed to fetch categories.");
  } finally {
    toast.dismiss(toastId);
  }
  return result;
};

// Add course details
export const addCourseDetails = async (data, token) => {
  const toastId = toast.loading("Adding course details...");
  let result = null;
  try {
    if (!token) {
      throw new Error("Authentication token is missing.");
    }
    const response = await apiConnector("POST", CREATE_COURSE_API, data, {
      "Content-Type": "multipart/form-data",
      Authorization: `Bearer ${token}`,
    });
    if (!response?.data?.success) {
      throw new Error(response.data.message || "Failed to add course details.");
    }
    result = response.data.data;
    toast.success("Course details added successfully!");
  } catch (error) {
    console.error("CREATE_COURSE_API ERROR:", error);
    toast.error(error.message || "Failed to add course details.");
  } finally {
    toast.dismiss(toastId);
  }
  return result;
};

// Edit course details
export const editCourseDetails = async (data, token) => {
  const toastId = toast.loading("Updating course details...");
  let result = null;
  try {
    if (!token) {
      throw new Error("Authentication token is missing.");
    }
    const response = await apiConnector("POST", EDIT_COURSE_API, data, {
      "Content-Type": "multipart/form-data",
      Authorization: `Bearer ${token}`,
    });
    if (!response?.data?.success) {
      throw new Error(response.data.message || "Failed to update course details.");
    }
    result = response.data.data;
    toast.success("Course details updated successfully!");
  } catch (error) {
    console.error("EDIT_COURSE_API ERROR:", error);
    toast.error(error.message || "Failed to update course details.");
  } finally {
    toast.dismiss(toastId);
  }
  return result;
};

// Fetch instructor courses
export const fetchInstructorCourses = async (token) => {
  const toastId = toast.loading("Loading your courses...");
  let result = [];
  try {
    if (!token) {
      throw new Error("Authentication token is missing.");
    }
    const response = await apiConnector("GET", GET_ALL_INSTRUCTOR_COURSES_API, null, {
      Authorization: `Bearer ${token}`,
    });
    if (!response?.data?.success) {
      throw new Error("Failed to fetch instructor courses.");
    }
    result = response.data.data;
    toast.success("Courses fetched successfully!");
  } catch (error) {
    console.error("INSTRUCTOR_COURSES_API ERROR:", error);
    toast.error(error.message || "Failed to fetch courses.");
  } finally {
    toast.dismiss(toastId);
  }
  return result;
};

// Delete a course
export const deleteCourse = async (data, token) => {
  const toastId = toast.loading("Deleting course...");
  try {
    if (!token) {
      throw new Error("Authentication token is missing.");
    }
    const response = await apiConnector("DELETE", DELETE_COURSE_API, data, {
      Authorization: `Bearer ${token}`,
    });
    if (!response?.data?.success) {
      throw new Error("Failed to delete course.");
    }
    toast.success("Course deleted successfully!");
  } catch (error) {
    console.error("DELETE_COURSE_API ERROR:", error);
    toast.error(error.message || "Failed to delete course.");
  } finally {
    toast.dismiss(toastId);
  }
};

// Mark lecture as complete
export const markLectureAsComplete = async (data, token) => {
  const toastId = toast.loading("Marking lecture as complete...");
  let result = false;
  try {
    if (!token) {
      throw new Error("Authentication token is missing.");
    }
    const response = await apiConnector("POST", LECTURE_COMPLETION_API, data, {
      Authorization: `Bearer ${token}`,
    });
    if (!response.data.message) {
      throw new Error(response.data.error || "Failed to mark lecture as complete.");
    }
    result = true;
    toast.success("Lecture marked as complete!");
  } catch (error) {
    console.error("LECTURE_COMPLETION_API ERROR:", error);
    toast.error(error.message || "Failed to mark lecture as complete.");
  } finally {
    toast.dismiss(toastId);
  }
  return result;
};

// Create a rating
export const createRating = async (data, token) => {
  const toastId = toast.loading("Creating rating...");
  let success = false;
  try {
    if (!token) {
      throw new Error("Authentication token is missing.");
    }
    const response = await apiConnector("POST", CREATE_RATING_API, data, {
      Authorization: `Bearer ${token}`,
    });
    if (!response?.data?.success) {
      throw new Error("Failed to create rating.");
    }
    success = true;
    toast.success("Rating created successfully!");
  } catch (error) {
    console.error("CREATE_RATING_API ERROR:", error);
    toast.error(error.message || "Failed to create rating.");
  } finally {
    toast.dismiss(toastId);
  }
  return success;
};
